function syncPageControls(){const page=pageSize(state.settings);$('pageWidth').value=page.widthCm;$('pageHeight').value=page.heightCm;$('aspectPreset').value=pagePreset(state.settings);$('map').style.aspectRatio=String(page.ratio);$('pageHint').textContent=tx('pageHint',{w:page.widthCm,h:page.heightCm});$('exportPageSize').textContent=`（${page.widthCm} × ${page.heightCm} cm）`;for(const option of $('exportWidth').options){const pixels=Number(option.value);option.textContent=tx('dpi',{pixels:pixels.toLocaleString(),dpi:Math.round(pixels/page.widthCm*2.54)});}try{const output=outputSize(state.settings,Number($('exportWidth').value));$('outputPixels').textContent=tx('output',{w:output.width.toLocaleString(),h:output.height.toLocaleString()});}catch(e){$('outputPixels').textContent=t(e.message);}}
