function activePoints(){return state.valid.filter(p=>state.selected.has(p.group));}
function updateSites(){const s=state.settings;state.catalog=siteCatalog(state.valid,s);state.sites=withSiteIds(groupSites(activePoints(),s.digits,s.pieMode,s.pies),state.catalog,s.pies);$('recordStat').textContent=state.valid.length.toLocaleString();$('siteStat').textContent=state.sites.length.toLocaleString();$('groupStat').textContent=`${state.selected.size}/${state.groups.length}`;updatePrecision();updateTable();scheduleDraw();}
function updatePrecision(){const lat=state.valid.length?state.valid.reduce((n,p)=>n+p.lat,0)/state.valid.length:23.5,d=precisionDistance(state.settings.digits,lat);const fmt=n=>n>=1000?`${(n/1000).toFixed(2)} km`:`${n.toFixed(n<10?2:0)} m`;$('precisionHint').textContent=tx('precision',{lat:lat.toFixed(1),east:fmt(d.east),north:fmt(d.north)});$('radiusOut').textContent=`${state.settings.radius} px`;$('shadowOut').textContent=`${Math.round(state.settings.shadow*100)}%`;}
function setPanel(name){for(const b of document.querySelectorAll('[data-panel]')){const on=b.dataset.panel===name;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on));}for(const n of ['data','style','export'])$('panel-'+n).hidden=n!==name;if(matchMedia('(max-width:800px)').matches)$('panel-'+name).scrollIntoView({behavior:'smooth',block:'start'});}
