$('saveProject').addEventListener('click',()=>{
 const project=createProject(state.raw,config(),{filename:state.filename,demo:state.demo,exportOptions:{prefix:$('prefix').value,format:$('format').value,width:Number($('exportWidth').value)}});
 download(new Blob([JSON.stringify(project)],{type:'application/json'}),safeName($('prefix').value)+'.tbm.json');
});
$('loadProject').addEventListener('click',()=>$('projectFile').click());
$('projectFile').addEventListener('change',async e=>{
 if(!e.target.files[0])return;const version=++fileReadVersion;
 try{
  const project=readProject(await e.target.files[0].text()),prepared=prepareConfig(project.config,project.data);
  if(version!==fileReadVersion)return;
  lastFile=null;installData(project.data,project.filename,project.demo);applyConfig(prepared);
  $('prefix').value=project.exportOptions.prefix;$('format').value=project.exportOptions.format;$('exportWidth').value=project.exportOptions.width;$('encoding').value='utf-8';syncPageControls();
  toast('已載入完整專案。');
 }catch(e){if(version===fileReadVersion)toast(t('完整專案讀取失敗：')+t(e.message));}finally{e.target.value='';}
});

const nextFrame=()=>new Promise(resolve=>requestAnimationFrame(()=>resolve()));
async function exportMap(batch=false){if(busy)return;if(!ready){toast('行政界線尚未載入。');return;}if(!activePoints().length){toast('請至少選擇一個有有效座標的物種。');return;}const status=renderer.status(state);if(!status.ready){toast(status.failed?'海拔圖磚載入失敗。請重新載入，或在樣式中關閉海拔底圖。':'目前範圍的海拔仍在載入，完成後即可匯出。');scheduleDraw();return;}busy=true;const snapshot={...state,settings:{...state.settings},camera:{...state.camera},colors:{...state.colors},groups:[...state.groups],selected:new Set(state.selected),columns:{...state.columns},referenceBounds:[...state.referenceBounds],sites:[...state.sites]};const points=[...activePoints()],selected=[...state.selected];$('exportBtn').disabled=$('batchBtn').disabled=$('topExport').disabled=true;const format=$('format').value,width=Number($('exportWidth').value),prefix=safeName($('prefix').value);try{const make=async sites=>{const c=document.createElement('canvas'),scene={...snapshot,sites};const result=renderer.render(scene,{canvas:c,width,svg:format==='svg'}),metadata=SOURCE+`; Demo=${snapshot.demo}; settings=${JSON.stringify(snapshot.settings)}; groups=${JSON.stringify(snapshot.groups)}`;if(format==='svg')return new Blob([result.svg],{type:'image/svg+xml;charset=utf-8'});const page=pageSize(snapshot.settings);if(format==='pdf')return pdfBlob(c,metadata,page);return await pngBlob(c,metadata,page);};if(!batch){$('exportStatus').textContent=t('正在繪製圖檔…');await nextFrame();const blob=await make(snapshot.sites);download(blob,`${prefix}.${format}`);$('exportStatus').textContent=tx('exported',{file:`${prefix}.${format}`});}else{const files=[],root=prefix+'_figures',all=snapshot.sites;let i=0;const jobs=[{name:'All',sites:all},...selected.map(g=>({name:g,sites:withSiteIds(groupSites(points.filter(p=>p.group===g),snapshot.settings.digits,snapshot.settings.pieMode,snapshot.settings.pies),snapshot.catalog,snapshot.settings.pies)}))];const names=new Set();for(const job of jobs){$('exportStatus').textContent=tx('rendering',{i:++i,n:jobs.length,name:job.name});await nextFrame();const name=uniqueName(job.name,names);files.push({name:`${root}/${name}/${prefix}_${name}.${format}`,data:await make(job.sites)},{name:`${root}/${name}/${prefix}_${name}_sites.csv`,data:siteTable(job.sites)});}files.push({name:`${root}/SOURCES.txt`,data:SOURCE+`\nDemonstration data: ${snapshot.demo}\nSVG terrain is embedded raster. PDF is a raster image.\nCoordinate grouping uses decimal rounding (ties to even), not a distance radius.\n`},{name:`${root}/settings.json`,data:JSON.stringify(config(snapshot),null,2)});$('exportStatus').textContent=t('正在整理 ZIP…');await nextFrame();download(await zipBlob(files),`${prefix}_figures.zip`);$('exportStatus').textContent=tx('batchDone',{n:selected.length});}toast('圖檔已準備好。');}catch(e){toast(tx('exportFailed',{reason:t(e.message)}));$('exportStatus').textContent=t('匯出失敗；可先降低解析度再試。');}finally{busy=false;$('exportBtn').disabled=$('batchBtn').disabled=$('topExport').disabled=false;scheduleDraw();}}
$('exportBtn').addEventListener('click',()=>exportMap());$('batchBtn').addEventListener('click',()=>exportMap(true));$('topExport').addEventListener('click',()=>{setPanel('export');});
for(const id of ['infoBtn','sourceBtn'])$(id).addEventListener('click',()=>$('infoDialog').showModal());$('closeInfo').addEventListener('click',()=>$('infoDialog').close());$('infoDialog').addEventListener('click',e=>{if(e.target===$('infoDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
setLanguage(readLanguage());state.language=getLanguage();applyLanguage();syncPageControls();demo();try{await renderer.init();ready=true;$('mapLoading').hidden=true;scheduleDraw();}catch(e){$('mapLoading').textContent=t(e.message)+' '+t('請重新整理網站。');toast(e.message);}
